/**
 * Checks for the ids a change points at. A reference into another
 * organization is a tenant violation; one that is missing, archived or
 * otherwise unusable is "not found".
 */
import { isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { NotFoundError, requireFound } from "./_support";
import type { CommentId, IssueId, LabelId, ProjectId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";

/** The user must be a current (not removed) member of the actor's org. */
export async function assertCurrentMember(
  actor: Actor,
  userId: UserId,
): Promise<void> {
  requireFound(await memberRepo.findMember(actor.orgId, userId), "Member", userId);
}

/** Every label must exist and belong to the actor's org. */
export async function assertOwnLabels(
  actor: Actor,
  labelIds: readonly LabelId[],
): Promise<void> {
  const unique = [...new Set(labelIds)];
  const found = await labelRepo.findLabelsByIdsAnyOrg(unique);
  const byId = new Map(found.map((label) => [label.id as string, label]));
  for (const id of unique) {
    const label = requireFound(byId.get(id), "Label", id);
    assertOrgScope(actor, label.orgId);
  }
}

/** A parent must be a live issue of the same project. */
export async function assertParentIssue(
  actor: Actor,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<void> {
  const parent = requireFound(
    await issueRepo.findIssueByIdAnyOrg(parentId),
    "Issue",
    parentId,
  );
  assertOrgScope(actor, parent.orgId);
  if (isArchived(parent) || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
}

/** A reply must target a live, top-level comment on the same issue. */
export async function assertReplyTarget(
  actor: Actor,
  issueId: IssueId,
  parentId: CommentId,
): Promise<void> {
  const parent = requireFound(
    await commentRepo.findCommentByIdAnyOrg(parentId),
    "Comment",
    parentId,
  );
  assertOrgScope(actor, parent.orgId);
  if (
    isArchived(parent) ||
    parent.issueId !== issueId ||
    parent.parentId !== null
  ) {
    throw new NotFoundError("Comment", parentId);
  }
}
EOF
